{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Elasticsearch domain encryption at rest is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "CRITICAL",
      "explanation": "Encryption at rest is disabled for the Elasticsearch domain. This exposes sensitive data stored in the domain to potential compromise if the underlying storage is accessed by unauthorized parties."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }
  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }
  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }
  encrypt_at_rest {
    enabled = true
  }
}",
  "fix_summary": "Enabled encryption at rest for the Elasticsearch domain by setting `encrypt_at_rest.enabled` to `true`."
}
